import type {
  ComprehensionQuestion,
  QuestionClassification,
  StoryLesson,
} from "../types";

type VocabularyDraft = readonly [
  word: string,
  definition: string,
  synonymOne: string,
  synonymTwo: string,
  hint: string,
];

type QuestionDraft = readonly [
  classification: QuestionClassification,
  prompt: string,
  modelAnswer: string,
  evidence: string,
  isOpinion?: boolean,
];

type LessonDraft = {
  sequence: number;
  title: string;
  genre: string;
  informational?: boolean;
  objective: string;
  skillTags: string[];
  subheadings: readonly [string, string];
  page1: readonly [string, string, string, string];
  page2: readonly [string, string, string, string];
  callouts: readonly [string, string];
  illustration: {
    alt: string;
    caption: string;
    sceneKey: string;
    accent: string;
  };
  vocabulary: readonly [VocabularyDraft, VocabularyDraft, VocabularyDraft];
  questions: readonly [
    QuestionDraft,
    QuestionDraft,
    QuestionDraft,
    QuestionDraft,
    QuestionDraft,
  ];
  paragraph: {
    prompt: string;
    centralIdea: string;
    topicStarter: string;
    details: readonly [string, string, string];
    irrelevant: readonly [string, string];
    missingDetailPrompt: string;
    conclusionPrompt: string;
    revisionPrompt: string;
    requiredVocabulary: string[];
    modelParagraph: string;
  };
  sources?: { label: string; url: string }[];
};

const makeQuestions = (
  lessonNumber: number,
  drafts: LessonDraft["questions"],
): StoryLesson["comprehension"] =>
  drafts.map(
    ([classification, prompt, modelAnswer, evidence, isOpinion], index) => ({
      id: `lesson-${lessonNumber}-question-${index + 1}`,
      classification,
      prompt,
      modelAnswer,
      evidence,
      ...(isOpinion ? { isOpinion: true } : {}),
    }),
  ) as [
    ComprehensionQuestion,
    ComprehensionQuestion,
    ComprehensionQuestion,
    ComprehensionQuestion,
    ComprehensionQuestion,
  ];

