const makeLesson = (draft: LessonDraft): StoryLesson => {
  const allParagraphs = [...draft.page1, ...draft.page2];
  const vocabulary = draft.vocabulary.map(
    ([word, definition, synonymOne, synonymTwo, hint]) => ({
      word,
      definition,
      synonyms: [synonymOne, synonymTwo] as [string, string],
      contextSentence:
        allParagraphs.find((paragraph) =>
          paragraph.toLocaleLowerCase().includes(word.toLocaleLowerCase()),
        ) ?? `The word ${word} is important to this lesson.`,
      hint,
    }),
  ) as StoryLesson["vocabulary"];

  const optionTexts = [...draft.paragraph.details, ...draft.paragraph.irrelevant];

  return {
    id: `story-lesson-${String(draft.sequence).padStart(3, "0")}`,
    sequence: draft.sequence,
    title: draft.title,
    genre: draft.genre,
    informational: draft.informational ?? false,
    grade: 5,
    band: draft.sequence <= 80 ? "advanced" : "mastery",
    objective: draft.objective,
    skillTags: draft.skillTags,
    pages: [
      {
        pageNumber: 1,
        subheading: draft.subheadings[0],
        paragraphs: [...draft.page1],
        callout: { label: "Detective Note", text: draft.callouts[0] },
      },
      {
        pageNumber: 2,
        subheading: draft.subheadings[1],
        paragraphs: [
          draft.page2[0],
          draft.page2[1],
          draft.page2[2],
          `${draft.page2[3]} ${passageExtensions[draft.sequence]}`,
        ],
        callout: {
          label: draft.informational ? "Key Idea" : "Evidence Box",
          text: draft.callouts[1],
        },
      },
    ],
    illustration: {
      src: `/story-adventures/illustrations/lesson-${String(draft.sequence).padStart(3, "0")}.svg`,
      ...draft.illustration,
    },
    vocabulary,
    comprehension: makeQuestions(draft.sequence, draft.questions),
    paragraphTask: {
      prompt: draft.paragraph.prompt,
      centralIdea: draft.paragraph.centralIdea,
      topicSentenceStarter: draft.paragraph.topicStarter,
      sentenceOptions: optionTexts.map((text, index) => ({
        id: `lesson-${draft.sequence}-sentence-${index + 1}`,
        text,
        relevant: index < 3,
        reason:
          index < 3
            ? "This detail directly supports the paragraph's central idea."
            : "This detail may be interesting, but it does not support the central idea.",
      })),
      missingDetailPrompt: draft.paragraph.missingDetailPrompt,
      conclusionPrompt: draft.paragraph.conclusionPrompt,
      revisionPrompt: draft.paragraph.revisionPrompt,
      requiredVocabulary: draft.paragraph.requiredVocabulary,
      modelParagraph: draft.paragraph.modelParagraph,
    },
    textFeatures: [
      {
        id: `lesson-${draft.sequence}-feature-title`,
        feature: "Title",
        location: "Above the two-page reading spread",
        purpose: "Introduces the lesson's central subject or mystery.",
        helpsBecause: "It prepares the reader to predict the main focus.",
      },
      {
        id: `lesson-${draft.sequence}-feature-subheading`,
        feature: "Subheading",
        location: `The page headings “${draft.subheadings[0]}” and “${draft.subheadings[1]}”`,
        purpose: "Divides the reading into two connected stages.",
        helpsBecause: "It shows how the ideas or events are organized.",
      },
      {
        id: `lesson-${draft.sequence}-feature-illustration`,
        feature: "Illustration with caption",
        location: "Beside the reading passage",
        purpose: "Shows an important scene or concept from the lesson.",
        helpsBecause: draft.illustration.caption,
      },
      {
        id: `lesson-${draft.sequence}-feature-callout`,
        feature: "Information box",
        location: "The coloured callout on each reading page",
        purpose: "Highlights a clue or key idea worth remembering.",
        helpsBecause: "It helps the reader connect important evidence across the passage.",
      },
    ],
    sourceReferences: draft.sources ?? [],
    contentVersion: "1.0.0",
  };
};

